function progress(step){return`<div class="progress" aria-label="首次梳理进度">${['说清选择','核对重点','看清下一步'].map((name,i)=>`<div class="progress-item ${i===step?'is-current':''} ${i<step?'is-done':''}" ${i===step?'aria-current="step"':''}><span>${i<step?'✓':`0${i+1}`}</span>${name}</div>`).join('')}</div>`;}
